# -*- coding: utf-8 -*-
# Devlet dini değişimi, devrimciler
L = ['en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'ar', 'fa', 'zh', 'ja', 'ko', 'hi']
T = {}
def a(tr, d):
    assert set(d) == set(L), (tr, set(L) ^ set(d))
    T[tr] = d
a('Devlet dini yeniden %d hafta sonra değiştirilebilir.', dict(en='The state religion can be changed again in %d weeks.', de='Die Staatsreligion kann in %d Wochen wieder geändert werden.', es='La religión de Estado podrá cambiarse de nuevo en %d semanas.', fr='La religion d’État pourra de nouveau changer dans %d semaines.', it='La religione di Stato potrà cambiare di nuovo tra %d settimane.', pt='A religião de Estado pode ser mudada de novo em %d semanas.', ru='Государственную религию можно снова сменить через %d нед.', ar='يمكن تغيير دين الدولة مجددًا بعد %d أسابيع.', fa='دین رسمی را %d هفته دیگر می‌توان دوباره تغییر داد.', zh='%d 周后才能再次更改国教。', ja='国教は%d週後に再び変更できる。', ko='%d주 후에 국교를 다시 바꿀 수 있다.', hi='राजधर्म %d सप्ताह बाद फिर बदला जा सकता है।'))
a('%s devlet dinini değiştirdi: %s.', dict(en='%s changed its state religion: %s.', de='%s änderte seine Staatsreligion: %s.', es='%s cambió su religión de Estado: %s.', fr='%s a changé de religion d’État : %s.', it='%s ha cambiato religione di Stato: %s.', pt='%s mudou a religião de Estado: %s.', ru='%s сменила государственную религию: %s.', ar='غيّرت %s دين الدولة: %s.', fa='%s دین رسمی را تغییر داد: %s.', zh='%s 更改了国教：%s。', ja='%sは国教を変更した：%s。', ko='%s가 국교를 바꿨다: %s.', hi='%s ने राजधर्म बदला: %s।'))
a('Devlet dinini değiştir (%s)', dict(en='Change state religion (%s)', de='Staatsreligion ändern (%s)', es='Cambiar religión de Estado (%s)', fr='Changer la religion d’État (%s)', it='Cambia religione di Stato (%s)', pt='Mudar religião de Estado (%s)', ru='Сменить госрелигию (%s)', ar='غيّر دين الدولة (%s)', fa='تغییر دین رسمی (%s)', zh='更改国教（%s）', ja='国教を変更（%s）', ko='국교 변경 (%s)', hi='राजधर्म बदलें (%s)'))
a('Devlet dini değişti.', dict(en='The state religion changed.', de='Die Staatsreligion wurde geändert.', es='La religión de Estado cambió.', fr='La religion d’État a changé.', it='La religione di Stato è cambiata.', pt='A religião de Estado mudou.', ru='Государственная религия сменилась.', ar='تغيّر دين الدولة.', fa='دین رسمی تغییر کرد.', zh='国教已更改。', ja='国教が変わった。', ko='국교가 바뀌었다.', hi='राजधर्म बदल गया।'))
a('Devlet dinini değiştir', dict(en='Change state religion', de='Staatsreligion ändern', es='Cambiar religión de Estado', fr='Changer la religion d’État', it='Cambia religione di Stato', pt='Mudar religião de Estado', ru='Сменить госрелигию', ar='غيّر دين الدولة', fa='تغییر دین رسمی', zh='更改国教', ja='国教を変更', ko='국교 변경', hi='राजधर्म बदलें'))
a('Şu anki devlet dini: %s. Değiştirmek %s tutar, istikrar 12 düşer ve 2 yıl yeniden değiştirilemez. Parantezde o inançtaki eyalet sayın.', dict(en='Current state religion: %s. Changing it costs %s, lowers stability by 12 and cannot be repeated for 2 years. In brackets: your provinces of that faith.', de='Aktuelle Staatsreligion: %s. Ein Wechsel kostet %s, senkt die Stabilität um 12 und ist 2 Jahre nicht wiederholbar. In Klammern: deine Provinzen dieses Glaubens.', es='Religión de Estado actual: %s. Cambiarla cuesta %s, baja la estabilidad 12 y no se repite en 2 años. Entre paréntesis: tus provincias de esa fe.', fr='Religion d’État actuelle : %s. La changer coûte %s, réduit la stabilité de 12 et n’est pas renouvelable avant 2 ans. Entre parenthèses : tes provinces de cette foi.', it='Religione di Stato attuale: %s. Cambiarla costa %s, riduce la stabilità di 12 e non si ripete per 2 anni. Tra parentesi: le tue province di quella fede.', pt='Religião de Estado atual: %s. Mudar custa %s, reduz a estabilidade em 12 e não pode repetir por 2 anos. Entre parênteses: tuas províncias dessa fé.', ru='Нынешняя госрелигия: %s. Смена стоит %s, снижает стабильность на 12 и невозможна повторно 2 года. В скобках — число твоих провинций этой веры.', ar='دين الدولة الحالي: %s. التغيير يكلف %s ويخفض الاستقرار 12 ولا يتكرر لعامين. بين القوسين: مقاطعاتك بذلك الدين.', fa='دین رسمی کنونی: %s. تغییرش %s هزینه دارد، ثبات را ۱۲ کم می‌کند و تا ۲ سال تکرارشدنی نیست. در پرانتز: استان‌های تو با آن دین.', zh='当前国教：%s。更改需花费 %s，稳定度下降 12，2 年内不能再改。括号内为该信仰的省份数。', ja='現在の国教：%s。変更には%sかかり、安定度が12下がり、2年間は再変更できない。括弧内はその信仰の州の数。', ko='현재 국교: %s. 변경 비용 %s, 안정도 12 하락, 2년간 재변경 불가. 괄호 안은 그 신앙의 지방 수.', hi='वर्तमान राजधर्म: %s। बदलने में %s लगते हैं, स्थिरता 12 घटती है और 2 साल तक दोबारा नहीं बदल सकते। कोष्ठक में उस आस्था के तुम्हारे प्रांत।'))
a('Geçersiz seçim.', dict(en='Invalid choice.', de='Ungültige Auswahl.', es='Opción no válida.', fr='Choix invalide.', it='Scelta non valida.', pt='Escolha inválida.', ru='Недопустимый выбор.', ar='اختيار غير صالح.', fa='انتخاب نامعتبر.', zh='无效的选择。', ja='無効な選択。', ko='잘못된 선택.', hi='अमान्य चयन।'))
a('Bu zaten devlet dini.', dict(en='That is already the state religion.', de='Das ist bereits die Staatsreligion.', es='Esa ya es la religión de Estado.', fr='C’est déjà la religion d’État.', it='È già la religione di Stato.', pt='Essa já é a religião de Estado.', ru='Это уже государственная религия.', ar='هذا هو دين الدولة بالفعل.', fa='این همین حالا دین رسمی است.', zh='这已是国教。', ja='それはすでに国教だ。', ko='이미 국교다.', hi='यह पहले से राजधर्म है।'))
a('Hükümet devrildi! Devrimciler başkenti ele geçirdi; yeni yönetim: %s.', dict(en='The government has fallen! Revolutionaries seized the capital; new regime: %s.', de='Die Regierung ist gestürzt! Revolutionäre nahmen die Hauptstadt ein; neues Regime: %s.', es='¡El gobierno ha caído! Los revolucionarios tomaron la capital; nuevo régimen: %s.', fr='Le gouvernement est tombé ! Les révolutionnaires ont pris la capitale ; nouveau régime : %s.', it='Il governo è caduto! I rivoluzionari hanno preso la capitale; nuovo regime: %s.', pt='O governo caiu! Os revolucionários tomaram a capital; novo regime: %s.', ru='Правительство свергнуто! Революционеры захватили столицу; новый режим: %s.', ar='سقطت الحكومة! استولى الثوار على العاصمة؛ النظام الجديد: %s.', fa='دولت سقوط کرد! انقلابیون پایتخت را گرفتند؛ حکومت جدید: %s.', zh='政府倒台！革命者占领了首都；新政权：%s。', ja='政府が倒れた！革命派が首都を掌握。新体制：%s。', ko='정부가 무너졌다! 혁명군이 수도를 장악했다. 새 체제: %s.', hi='सरकार गिर गई! क्रांतिकारियों ने राजधानी पर कब्ज़ा किया; नई व्यवस्था: %s।'))
a('Devrimciler ayaklandı: %s yakınında hükümeti devirmek için silaha sarıldılar.', dict(en='Revolutionaries rose up near %s, taking up arms to overthrow the government.', de='Revolutionäre erhoben sich nahe %s, um die Regierung zu stürzen.', es='Revolucionarios se alzaron cerca de %s para derrocar al gobierno.', fr='Des révolutionnaires se soulèvent près de %s pour renverser le gouvernement.', it='Rivoluzionari insorgono vicino a %s per rovesciare il governo.', pt='Revolucionários revoltaram-se perto de %s para derrubar o governo.', ru='Революционеры восстали у %s, чтобы свергнуть правительство.', ar='ثار ثوار قرب %s وحملوا السلاح لإسقاط الحكومة.', fa='انقلابیون نزدیک %s برای سرنگونی دولت دست به سلاح بردند.', zh='革命者在 %s 附近起事，企图推翻政府。', ja='革命派が%s近くで蜂起し、政府打倒のため武器を取った。', ko='혁명군이 %s 근처에서 정부를 무너뜨리려 봉기했다.', hi='क्रांतिकारी %s के पास सरकार गिराने के लिए हथियार उठाकर उठ खड़े हुए।'))
